CREATE TABLE skus (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_by text NOT NULL, sku_code text NOT NULL, product_name text NOT NULL, category text, platform text NOT NULL, selling_price numeric(12,2) NOT NULL DEFAULT 0, cost_per_unit numeric(12,2) NOT NULL DEFAULT 0, opening_stock numeric(12,2) NOT NULL DEFAULT 0, reorder_level numeric(12,2) NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true, notes text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(created_by, sku_code, platform))